python3 - <<'EOF'
import json
p=".claude-home/projects/-home-runner-workspace/527663fc-a563-4d60-bbbb-546c4c716bfc.jsonl"
lines=[json.loads(l) for l in open(p) if l.strip()]
res={}
for e in lines:
    if e.get("type")=="user":
        c=(e.get("message") or {}).get("content") or []
        if isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get("type")=="tool_result":
                    t=b.get("content")
                    if isinstance(t,list): t=" ".join(x.get("text","") for x in t if isinstance(x,dict))
                    res[b.get("tool_use_id")]=str(t)
for i,e in enumerate(lines):
    if e.get("type")!="assistant": continue
    for b in (e.get("message") or {}).get("content") or []:
        if isinstance(b,dict) and b.get("type")=="tool_use":
            if i<80: continue
            inp=b.get("input",{})
            desc=inp.get("command") or inp.get("file_path") or inp.get("pattern") or str(inp)[:120]
            print(f"[{i}] {b['name']}: {str(desc)[:200]}")
            r=res.get(b['id'],"")
            print(f"    -> {r[:400]}".replace("\n","\n    "))
EOF

