 1	import { useEffect, useState, useTransition } from "react";
 2	import { useLocation } from "wouter";
 3	import { TERMINAL_DOCK_ITEMS, TerminalDockView, type TerminalDockMode } from "@/features/navigation/TerminalDockView";
 4	
 5	const RETAIL_NAV_PATHS = ["/dashboard", "/stock", "/transactions", "/settings", "/terminal"];
 6	
 7	function readMode(): TerminalDockMode {
 8	  try { return (localStorage.getItem("taptMode") as TerminalDockMode) || "retail"; }
 9	  catch { return "retail"; }
10	}
11	function saveMode(mode: TerminalDockMode) {
12	  try { localStorage.setItem("taptMode", mode); }
13	  catch { /* Route-derived navigation still works without storage. */ }
14	}
15	const itemIsActive = (path: string, location: string) => {
16	  if (path === "/dashboard" || path === "/property" || path === "/trades") return location === path;
17	  if (path === "/settings" || path === "/terminal" || path === "/trades/terminal") return location === path;
18	  return location === path || location.startsWith(`${path}/`);
19	};
20	
21	export function BottomNavigation() {
22	  const [location, setLocation] = useLocation();
23	  const [, startTransition] = useTransition();
24	  const [storedMode, setStoredMode] = useState<TerminalDockMode>(readMode);
25	
26	  useEffect(() => {
27	    if (location.startsWith("/trades")) { saveMode("trades"); setStoredMode("trades"); }
28	    else if (location.startsWith("/property")) { saveMode("property"); setStoredMode("property"); }
29	    else if (RETAIL_NAV_PATHS.includes(location) && location !== "/settings") { saveMode("retail"); setStoredMode("retail"); }
30	  }, [location]);
31	
32	  const isTradesMode = location.startsWith("/trades") || storedMode === "trades";
33	  const isPropertyMode = !isTradesMode && (location.startsWith("/property") || storedMode === "property");
34	  const mode: TerminalDockMode = isTradesMode ? "trades" : isPropertyMode ? "property" : "retail";
35	  const onRetailPage = RETAIL_NAV_PATHS.includes(location);
36	  const onPropertyPage = location.startsWith("/property");
37	  const onTradesPage = location.startsWith("/trades") && !location.startsWith("/trades/quote/");
38	  if (!onRetailPage && !onPropertyPage && !onTradesPage) return null;
39	
40	  const activeItem = TERMINAL_DOCK_ITEMS[mode].find((item) => itemIsActive(item.path, location));
41	  return <TerminalDockView mode={mode} activeId={activeItem?.id ?? ""} onPick={({ path }) => startTransition(() => setLocation(path))} />;
42	}

