    if (mid.rect > DOCK_COLLAPSED + 1 && mid.rect < DOCK_EXPANDED - 1 && mid.px === DOCK_EXPANDED) {
      fail(
        `${label}: --dock-h stayed at ${DOCK_EXPANDED}px through a collapse in progress (§4.3 clause 8)`,
      );
    }
  }

  /* Collapsed: wait out the rest of the idle timer and re-read. */
  await page.waitForTimeout(1_200);"""
